// The Daily Telegraph: issue types, loading, normalizing, numbering, and the 7-day window.
//
// Where issues live: one JSON file per day at data/telegraph/YYYY-MM-DD.json, in Thaddeus Pendelton's
// format (see /home/box/shared/telegraph/SAMPLE-schema.json). data/telegraph/index.ts imports them all
// and is regenerated by scripts/telegraph-publish.mjs, which also prunes files older than 7 days.
// Only issues from today plus the 6 prior days (local time) are shown.

import { getLocalDateString } from '@/lib/dates';
import { RAW_ISSUES } from '@/data/telegraph';

export type SectionId =
  | 'front'
  | 'local'
  | 'us-world'
  | 'markets'
  | 'sports'
  | 'irreverent'
  | 'weather';

// URL slug, label, and the matching key in the JSON file.
export const SECTIONS: { id: SectionId; label: string; key: string }[] = [
  { id: 'front', label: 'Front Page', key: 'front_page' },
  { id: 'local', label: 'Local', key: 'local' },
  { id: 'us-world', label: 'US and World', key: 'us_world' },
  { id: 'markets', label: 'Markets', key: 'markets' },
  { id: 'sports', label: 'Sports', key: 'sports' },
  { id: 'irreverent', label: 'Irreverent', key: 'irreverent' },
  { id: 'weather', label: 'Weather', key: 'weather' },
];

// ---- File format (as written by Thaddeus; everything optional except what we can't live without) ----

export type RawStory = {
  headline: string;
  summary?: string;
  source_name?: string;
  source_url?: string;
  published_at?: string;
  from_section?: string;
  location?: string;
  impact?: string;
  composite_score?: number;
  // Extras used by the pretend Oct 17 issue
  byline?: string;
  body?: string[];
};

export type Macd = {
  macd: number | null;
  signal: number | null;
  histogram: number | null;
};

export type MarketRow = {
  name: string;
  symbol: string;
  last_close?: number | null;
  pct_day?: number | null;
  pct_week?: number | null;
  pct_month?: number | null;
  pct_ytd?: number | null;
  vs_40wk_sma?: string | null;
  rsi_14?: number | null;
  rsi_series?: (number | null)[];
  macd?: Macd | null;
  macd_series?: (Macd | null)[];
};

export type Score = {
  team: string;
  opponent?: string;
  score?: string;
  result?: string;
  date?: string;
  source_url?: string;
};

export type RawSection = {
  status?: string;
  stories?: RawStory[];
  // markets
  as_of_close?: string;
  table?: MarketRow[];
  breadth?: {
    label?: string;
    value?: number;
    prior_value?: number;
    direction?: string;
    reading?: string;
    note?: string;
  };
  summary?: string;
  portfolio_news?: { symbol: string; stories?: RawStory[] }[];
  headlines?: RawStory[];
  // sports
  scores?: Score[];
  // weather
  maps?: {
    title?: string;
    image_url: string;
    source_name?: string;
    source_url?: string;
  }[];
};

export type RawIssue = {
  edition_date: string;
  generated_at?: string;
  editor?: string;
  sections?: Record<string, RawSection | undefined>;
};

// ---- Normalized shapes used by the page and card ----

export type Story = RawStory & { id: string };

export type Section = Omit<RawSection, 'stories' | 'headlines'> & {
  available: boolean;
  stories: Story[];
};

export type Issue = {
  date: string;
  generatedAt?: string;
  editor?: string;
  sections: Record<SectionId, Section>;
};

const OK_STATUS = ['complete', 'partial', 'ok'];

function normalize(raw: RawIssue): Issue {
  const sections = {} as Record<SectionId, Section>;
  for (const { id, key } of SECTIONS) {
    const s = raw.sections?.[key];
    const list = [...(s?.stories ?? []), ...(s?.headlines ?? [])];
    sections[id] = {
      ...s,
      available:
        !!s && OK_STATUS.includes((s.status ?? 'complete').toLowerCase()),
      stories: list
        .filter((st) => st && st.headline)
        .map((st, i) => ({ ...st, id: `${id}-${i}` })),
    };
  }
  return {
    date: raw.edition_date,
    generatedAt: raw.generated_at,
    editor: raw.editor,
    sections,
  };
}

export const ISSUES: Issue[] = (RAW_ISSUES as RawIssue[])
  .filter((r) => /^\d{4}-\d{2}-\d{2}$/.test(r?.edition_date ?? ''))
  .map(normalize);

export const WINDOW_DAYS = 7;

const ROMAN: [number, string][] = [
  [1000, 'M'],
  [900, 'CM'],
  [500, 'D'],
  [400, 'CD'],
  [100, 'C'],
  [90, 'XC'],
  [50, 'L'],
  [40, 'XL'],
  [10, 'X'],
  [9, 'IX'],
  [5, 'V'],
  [4, 'IV'],
  [1, 'I'],
];

export function toRoman(n: number): string {
  let out = '';
  for (const [v, r] of ROMAN)
    while (n >= v) {
      out += r;
      n -= v;
    }
  return out;
}

// Whole days between two YYYY-MM-DD dates (calendar math via UTC components, so no DST/zone drift).
function dayDiff(from: string, to: string): number {
  const ms = (d: string) => {
    const [y, m, day] = d.split('-').map(Number);
    return Date.UTC(y, m - 1, day);
  };
  return Math.round((ms(to) - ms(from)) / 86400000);
}

const FIRST_ISSUE = '2026-10-17';

// Volume = year - 2025. No. 1 on 2026-10-17, +1 per day, resets to No. 1 every Jan 1 (so day of year from 2027).
export function issueNumbering(date: string): {
  volume: number;
  number: number;
  label: string;
} {
  const year = Number(date.slice(0, 4));
  const volume = year - 2025;
  const start = year === 2026 ? FIRST_ISSUE : `${year}-01-01`;
  const number = dayDiff(start, date) + 1;
  return { volume, number, label: `Vol. ${toRoman(volume)} · No. ${number}` };
}

// Issues within the rolling window (today + 6 prior), newest first.
export function getRecentIssues(today = getLocalDateString()): Issue[] {
  return ISSUES.filter((i) => {
    const age = dayDiff(i.date, today);
    return age >= 0 && age < WINDOW_DAYS;
  }).sort((a, b) => b.date.localeCompare(a.date));
}

// The requested issue if it's in the window, otherwise the latest one (or undefined if none).
export function resolveIssue(
  date: string | null,
  today = getLocalDateString(),
): Issue | undefined {
  const recent = getRecentIssues(today);
  return recent.find((i) => i.date === date) ?? recent[0];
}

// Latest issue and its top front-page headlines for the dashboard card.
export function getTopHeadlines(limit = 5): {
  issue?: Issue;
  stories: Story[];
} {
  const issue = resolveIssue(null);
  return {
    issue,
    stories: issue?.sections.front.stories.slice(0, limit) ?? [],
  };
}

// Deep link to a story inside a given issue (front-page story ids are 'front-N').
export function storyHref(issue: Issue, story: Story): string {
  const section = story.id.slice(0, story.id.lastIndexOf('-'));
  return `/telegraph?issue=${issue.date}&section=${section}#${story.id}`;
}

// Label for a JSON section key such as 'us_world' (used for "from" tags on front-page stories).
export function sectionLabel(key?: string): string | undefined {
  return SECTIONS.find((s) => s.key === key || s.id === key)?.label;
}
